        assertEquals(1, Integer.parseInt(appVersion.getVersion().split("-")[0]));
    }

    @Test
    public void compareTo_DifferentBuildNumbers_ComparedToLessThan() {
        AppVersion appVersion1 = AppVersion.parseName("2.0-ami-1234567890");
